python3 - <<'PY'
import json, importlib, glob, os
fail=0
for path in sorted(glob.glob('examples/*.json')):
    service=os.path.basename(path)[:-5]
    mod=importlib.import_module('clients.'+service)
    for i, case in enumerate(json.load(open(path))):
        try:
            got={'ok': mod.normalize(case['record'])}
        except Exception as e:
            got={'err': type(e).__name__}
        if got != case['result']:
            fail += 1
            print(service, i, 'FAIL')
            print(' expected:', case['result'])
            print(' got     :', got)
print('failures:', fail)
PY
